/* gradient section ------------------------------------------------------- */
.bp-gradient{background:linear-gradient(120deg,#0A1430,#18306A 35%,#7A0F18 70%,#0A1430);background-size:300% 300%;animation:bpGrad 18s ease infinite}
@keyframes bpGrad{0%,100%{background-position:0% 50%}50%{background-position:100% 50%}}
/* stats ------------------------------------------------------------------ */
.bp-stats{background-size:cover;background-position:center}
.bp-stats:before{content:"";position:absolute;inset:0;z-index:-1;background:linear-gradient(90deg,rgba(5,9,19,.92),rgba(10,20,48,.78))}
.bp-stat{padding:34px 28px!important;flex-direction:row!important;align-items:center;gap:20px!important}
.bp-stat .elementor-icon{width:66px;height:66px;font-size:26px!important;display:grid!important;place-items:center;border-radius:18px;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.16);color:#fff!important}
.bp-stat .elementor-icon svg{fill:#fff!important;width:28px;height:28px}
.bp-stat .elementor-counter{flex-direction:column;align-items:flex-start!important}
.bp-stat .elementor-counter-number-wrapper{font-family:var(--bp-fh);font-stretch:118%;font-weight:900;font-size:clamp(44px,4.5vw,64px)!important;line-height:1;color:#fff!important;letter-spacing:-.04em;justify-content:flex-start!important}
.bp-stat .elementor-counter-number-suffix{color:var(--bp-red)}
.bp-stat .elementor-counter-title{font-size:15px!important;font-weight:600;color:#B9C3DC!important;text-align:left!important;justify-content:flex-start!important;line-height:1.4;margin-top:6px}
/* brands ----------------------------------------------------------------- */
.bp-brands{gap:18px!important}
.bp-brand{flex:1 1 0!important;min-width:110px;padding:18px!important;display:grid!important;place-items:center;height:120px;border-radius:18px;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.08);transition:transform .45s var(--bp-ease),background .45s,border-color .45s}
.bp-brand img{max-height:74px;width:auto!important;filter:grayscale(1) brightness(1.4);opacity:.75;transition:filter .45s,opacity .45s;border-radius:8px}
.bp-brand:hover{transform:translateY(-6px);background:rgba(255,255,255,.08);border-color:rgba(255,255,255,.2)}
.bp-brand:hover img{filter:none;opacity:1}
/* carousel --------------------------------------------------------------- */
.bp-carousel .swiper-slide{border-radius:20px;overflow:hidden}
.bp-carousel .swiper-slide-image{width:100%;aspect-ratio:3/4;object-fit:cover;border-radius:20px;transition:transform 1s var(--bp-ease)}
.bp-carousel .swiper-slide:hover .swiper-slide-image{transform:scale(1.06)}
.bp-carousel .elementor-swiper-button{width:52px;height:52px;border-radius:50%;background:rgba(255,255,255,.75);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);display:grid!important;place-items:center;box-shadow:var(--bp-sh);color:var(--bp-head)!important;font-size:18px!important;transition:background .3s,transform .3s}
.bp-carousel .elementor-swiper-button svg{fill:var(--bp-head)!important;width:18px;height:18px}
.bp-carousel .elementor-swiper-button:hover{background:#fff;transform:scale(1.08)}
.bp-carousel .swiper-pagination-bullet{width:8px;height:8px;transition:width .3s,background .3s}
.bp-carousel .swiper-pagination-bullet-active{width:26px;border-radius:6px;background:var(--bp-red)!important}
/* video frame ------------------------------------------------------------ */
.bp-video .elementor-wrapper,.bp-video video{border-radius:26px;overflow:hidden;box-shadow:var(--bp-sh-lg)}
.bp-video{padding:10px!important;border-radius:32px!important}
/* CTA band --------------------------------------------------------------- */
.bp-cta{background:linear-gradient(120deg,var(--bp-red-2),var(--bp-red) 45%,#FF4B3E 70%,var(--bp-red-2));background-size:250% 250%;animation:bpGrad 12s ease infinite;text-align:center}
.bp-cta:before{content:"";position:absolute;inset:-50%;z-index:-1;background:repeating-linear-gradient(-45deg,rgba(255,255,255,.06) 0 30px,transparent 30px 60px);animation:bpLines 14s linear infinite}
.bp-cta:after{content:"";position:absolute;width:700px;height:700px;left:50%;top:50%;transform:translate(-50%,-50%);z-index:-1;border-radius:50%;background:radial-gradient(circle,rgba(255,255,255,.18),transparent 60%)}
.bp-cta .elementor-heading-title{color:#fff;font-size:clamp(32px,5vw,68px);text-align:center}
.bp-cta .bp-t{color:rgba(255,255,255,.88);font-size:clamp(16px,1.4vw,20px);text-align:center;max-width:720px;margin:0 auto}
.bp-cta>.e-con-inner{align-items:center;gap:26px}
/* contact ---------------------------------------------------------------- */
.bp-contact{background-size:cover;background-position:center}
.bp-contact:before{content:"";position:absolute;inset:0;z-index:-1;background:linear-gradient(110deg,rgba(5,9,19,.97) 30%,rgba(10,20,48,.85))}
/* FAQ -------------------------------------------------------------------- */
.bp-faq-side{position:sticky!important;top:calc(var(--bp-hdr) + 40px);align-self:flex-start}
.bp-faq .e-n-accordion{display:flex;flex-direction:column;gap:14px}
.bp-faq .e-n-accordion-item{border-radius:18px;background:#fff;border:1px solid var(--bp-line);box-shadow:0 10px 26px -20px rgba(10,20,48,.4);overflow:hidden;transition:border-color .35s,box-shadow .35s}
.bp-faq .e-n-accordion-item[open]{border-color:rgba(229,34,45,.35);box-shadow:0 26px 50px -30px rgba(10,20,48,.45)}
.bp-faq .e-n-accordion-item-title{padding:22px 26px!important;background:transparent!important;border:0!important;cursor:pointer;display:flex;justify-content:space-between;align-items:center;gap:20px}
.bp-faq .e-n-accordion-item-title-text{font-family:var(--bp-fh);font-stretch:106%;font-weight:700;font-size:clamp(16px,1.3vw,19px);line-height:1.35;color:var(--bp-head)!important;letter-spacing:-.01em}
.bp-faq .e-n-accordion-item-title-icon{width:38px;height:38px;flex:0 0 38px;border-radius:50%;display:grid!important;place-items:center;background:var(--bp-bg);transition:background .35s,transform .45s var(--bp-ease)}
.bp-faq .e-n-accordion-item-title-icon svg{width:14px;height:14px;fill:var(--bp-head)!important}
.bp-faq .e-n-accordion-item[open] .e-n-accordion-item-title-icon{background:var(--bp-red);transform:rotate(180deg)}
.bp-faq .e-n-accordion-item[open] .e-n-accordion-item-title-icon svg{fill:#fff!important}
.bp-faq .e-n-accordion-item>.e-con{padding:0 26px 24px!important;border:0!important;background:transparent!important}
.bp-faq .e-n-accordion-item .bp-t{font-size:15.5px}
/* reviews ---------------------------------------------------------------- */
.bp-reviews{min-height:120px}
/* reveal (JS enhanced, reduced-motion safe) ---------------------------------- */
.bp-js .bp-rv{opacity:0;transform:translateY(26px);transition:opacity .9s var(--bp-ease),transform .9s var(--bp-ease)}
.bp-js .bp-rv.is-in{opacity:1;transform:none}
.bp .animated.fadeInUp{animation-name:bpFadeUp}
.bp .animated.fadeInLeft{animation-name:bpFadeLeft}
.bp .animated.fadeInRight{animation-name:bpFadeRight}
.bp .animated.zoomIn{animation-name:bpZoom}
.bp .animated{animation-timing-function:var(--bp-ease)!important;animation-duration:1s}
@keyframes bpFadeUp{from{opacity:0;transform:translate3d(0,36px,0)}to{opacity:1;transform:none}}
@keyframes bpFadeLeft{from{opacity:0;transform:translate3d(-48px,0,0)}to{opacity:1;transform:none}}
@keyframes bpFadeRight{from{opacity:0;transform:translate3d(48px,0,0)}to{opacity:1;transform:none}}
@keyframes bpZoom{from{opacity:0;transform:scale(.94)}to{opacity:1;transform:none}}
.bp-progress{position:fixed;left:0;top:0;height:3px;width:100%;z-index:100000;transform-origin:0 50%;transform:scaleX(0);background:linear-gradient(90deg,var(--bp-red),#FF6B5E,var(--bp-blue));pointer-events:none}
/* header ----------------------------------------------------------------- */
.bp-header{position:fixed!important;top:0;left:0;right:0;z-index:999;transition:transform .45s var(--bp-ease)}
body.admin-bar .bp-header{top:32px}
.bp-topbar{padding:9px 0!important;font-size:13.5px;border-bottom:1px solid rgba(255,255,255,.08);transition:margin .45s var(--bp-ease),opacity .3s;background:rgba(5,9,19,.55)}
.bp-topbar .elementor-icon-list-text{color:#C9D2E8!important;font-weight:600}
.bp-topbar a:hover .elementor-icon-list-text{color:#fff!important}
.bp-topbar .elementor-icon-list-icon svg{fill:var(--bp-red)!important;width:13px}
.bp-topbar .elementor-icon-list-icon i{color:var(--bp-red)!important}
.bp-topbar .elementor-icon-list-items{gap:22px}
.bp-mainbar{padding:14px 0!important;transition:padding .45s var(--bp-ease),background .45s,box-shadow .45s;background:linear-gradient(180deg,rgba(5,9,19,.55),rgba(5,9,19,0))}
.bp-header.is-scrolled .bp-mainbar{padding:8px 0!important;background:rgba(8,14,32,.72);-webkit-backdrop-filter:blur(18px) saturate(170%);backdrop-filter:blur(18px) saturate(170%);box-shadow:0 1px 0 rgba(255,255,255,.08),0 20px 40px -24px rgba(0,0,0,.7)}
.bp-header.is-scrolled .bp-topbar{margin-top:-38px;opacity:0;pointer-events:none}
.bp-logo img{width:92px!important;height:auto;transition:width .45s var(--bp-ease);filter:drop-shadow(0 8px 18px rgba(0,0,0,.45))}
.bp-header.is-scrolled .bp-logo img{width:72px!important}
.bp-nav{flex:1 1 auto!important}
.bp-nav .elementor-nav-menu--main .elementor-item{font-family:var(--bp-fh);font-stretch:106%;font-weight:600;font-size:15.5px;color:#fff!important;padding:10px 16px!important;border-radius:999px;transition:background .3s,color .3s}
.bp-nav .elementor-nav-menu--main .elementor-item:hover,.bp-nav .elementor-nav-menu--main .elementor-item.elementor-item-active{background:rgba(255,255,255,.1);color:#fff!important}
.bp-nav .elementor-nav-menu--main .elementor-item:after,.bp-nav .elementor-nav-menu--main .elementor-item:before{display:none!important}
.bp-nav .elementor-nav-menu--main .sub-menu{border-radius:18px!important;padding:10px!important;background:rgba(10,20,48,.86)!important;-webkit-backdrop-filter:blur(20px) saturate(160%);backdrop-filter:blur(20px) saturate(160%);border:1px solid rgba(255,255,255,.12);box-shadow:0 30px 60px -20px rgba(0,0,0,.7);min-width:280px!important;animation:bpDrop .3s var(--bp-ease)}
@keyframes bpDrop{from{opacity:0;transform:translateY(10px)}}
.bp-nav .sub-menu .elementor-sub-item{color:#D5DCEE!important;background:transparent!important;border-radius:10px;padding:11px 14px!important;font-weight:600;font-size:14.5px;transition:background .25s,color .25s,padding .25s}
.bp-nav .sub-menu .elementor-sub-item:hover{background:rgba(255,255,255,.08)!important;color:#fff!important;padding-left:20px!important}
.bp-nav .elementor-menu-toggle{background:rgba(255,255,255,.1)!important;border:1px solid rgba(255,255,255,.2);border-radius:12px;padding:10px!important;color:#fff!important}
.bp-nav .elementor-menu-toggle svg{fill:#fff!important}
.bp-nav .elementor-nav-menu--dropdown{background:rgba(8,14,32,.94)!important;-webkit-backdrop-filter:blur(20px);backdrop-filter:blur(20px);border-radius:18px;margin-top:14px!important;border:1px solid rgba(255,255,255,.12);overflow:hidden}
.bp-nav .elementor-nav-menu--dropdown a{color:#E3E8F5!important;background:transparent!important;font-weight:600;padding:14px 22px!important;border-bottom:1px solid rgba(255,255,255,.06)}
.bp-nav .elementor-nav-menu--dropdown a:hover,.bp-nav .elementor-nav-menu--dropdown a.elementor-item-active{color:#fff!important;background:rgba(229,34,45,.25)!important}
.bp-hdr-cta .elementor-button{padding:14px 22px;font-size:15px}
/* footer ----------------------------------------------------------------- */
.bp-footer{background:var(--bp-ink);color:#9FAAC6;padding:clamp(64px,8vw,104px) 0 0!important;overflow:hidden;position:relative;isolation:isolate}
.bp-footer .elementor-heading-title{font-size:15px;font-stretch:110%;letter-spacing:.12em;text-transform:uppercase;color:#fff;margin-bottom:6px}
.bp-footer .bp-t{font-size:15px;color:#9FAAC6}
.bp-flinks .elementor-icon-list-item{padding:6px 0!important}
.bp-flinks .elementor-icon-list-text{color:#B7C1DA!important;font-size:15px;transition:color .25s,transform .25s var(--bp-ease);display:inline-block}
.bp-flinks a:hover .elementor-icon-list-text{color:#fff!important;transform:translateX(5px)}
.bp-flinks .elementor-icon-list-icon svg{fill:var(--bp-red)!important;width:14px}
.bp-flinks .elementor-icon-list-icon i{color:var(--bp-red)!important}
.bp-flinks.bp-dots .elementor-icon-list-icon svg{width:6px}
.bp-social .elementor-social-icon{background:rgba(255,255,255,.07)!important;border:1px solid rgba(255,255,255,.14);border-radius:12px!important;transition:background .3s,transform .3s var(--bp-ease)}
.bp-social .elementor-social-icon:hover{background:var(--bp-red)!important;transform:translateY(-3px)}
.bp-social .elementor-social-icon svg{fill:#fff!important}
.bp-map iframe{width:100%!important;height:220px!important;border-radius:18px!important;filter:grayscale(.6) contrast(1.05);transition:filter .5s}
.bp-map iframe:hover{filter:none}
.bp-copy{margin-top:64px!important;padding:24px 0!important;border-top:1px solid rgba(255,255,255,.08);font-size:14px;text-align:center}
.bp-wordmark{position:absolute;left:50%;bottom:-.18em;transform:translateX(-50%);font-family:var(--bp-fh);font-stretch:125%;font-weight:900;font-size:clamp(90px,17vw,260px);line-height:1;letter-spacing:-.05em;color:transparent;-webkit-text-stroke:1px rgba(255,255,255,.06);white-space:nowrap;pointer-events:none;z-index:-1}
/* responsive ------------------------------------------------------------- */
@media (max-width:1024px){
  :root{--bp-hdr:76px}
  .bp-grid-3,.bp-grid-4{grid-template-columns:repeat(2,minmax(0,1fr))}
  .bp-row.bp-stack-t,.bp-row.bp-stack-t>.e-con-inner{flex-direction:column!important}
  .bp-hero>.e-con-inner{flex-direction:column!important;align-items:stretch}
  .bp-hero-side{flex:1 1 auto!important;max-width:640px}
  .bp-faq-side{position:relative!important;top:0}
  .bp-topbar{display:none}
  .bp-badge{left:12px}
}
@media (max-width:767px){
  :root{--bp-hdr:68px;--bp-r:18px}
  .bp.e-con-boxed>.e-con-inner,.bp .e-con-boxed>.e-con-inner{padding-left:16px;padding-right:16px}
  .bp-row,.bp-row>.e-con-inner{flex-direction:column!important}
  .bp-row.bp-keep,.bp-row.bp-keep>.e-con-inner{flex-direction:row!important}
  .bp-grid-2,.bp-grid-3,.bp-grid-4,.bp-list ul,.bp-ticks .elementor-icon-list-items{grid-template-columns:1fr}
  .bp-hero{min-height:auto;padding-bottom:90px!important}
  .bp-hero:after,.bp-aura:before,.bp-aura:after{display:none}
  .bp-glass{-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px)}
  .bp-svc .bp-card{-webkit-backdrop-filter:none;backdrop-filter:none;background:rgba(16,31,71,.9)}
  .bp-formcard{padding:26px 20px!important}
  .bp-frame:before{inset:14px -10px -14px 10px}
  .bp-badge{left:12px;bottom:16px}
  .bp-brand{flex:1 1 calc(33% - 12px)!important;min-width:0;height:90px}
  .bp-brand img{max-height:54px}
  .bp-logo img{width:70px!important}
  .bp-wordmark{display:none}
  .bp-scrollcue{display:none}
}
@media (prefers-reduced-motion:reduce){
  .bp *,.bp *:before,.bp *:after,.bp:before,.bp:after{animation:none!important;transition:none!important}
  .bp-js .bp-rv{opacity:1;transform:none}
  .bp .elementor-invisible{visibility:visible!important}
}
body.elementor-editor-active .bp-rv{opacity:1!important;transform:none!important}
body.elementor-editor-active .bp-header{position:relative!important}
/* eyebrow on light surfaces */
.bp-light .bp-eyebrow .elementor-heading-title,.bp-soft .bp-eyebrow .elementor-heading-title,.bp-on-light .bp-eyebrow .elementor-heading-title{color:var(--bp-red);background:rgba(229,34,45,.07);border-color:rgba(229,34,45,.18);-webkit-backdrop-filter:none;backdrop-filter:none}
.bp-light .bp-eyebrow .elementor-heading-title:before,.bp-soft .bp-eyebrow .elementor-heading-title:before{background:var(--bp-red);animation:none}
.bp-eyebrow{margin-bottom:18px!important}
.bp-head-c .bp-eyebrow{align-self:center}
/* footer grid */
.bp-fgrid{display:grid!important;grid-template-columns:1.35fr 1fr .8fr 1.15fr 1.35fr;gap:40px}
.bp-footer .bp-logo img{width:110px!important}
.bp-footer .bp-t em{font-style:normal}
@media (max-width:1024px){.bp-fgrid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:767px){.bp-fgrid{grid-template-columns:1fr;gap:34px}}
/* ---- fixes v2 ---- */
.bp-row>.e-con,.bp-row>.e-con-inner>.e-con{flex:1 1 0;min-width:0}
.bp-row>.bp-auto,.bp-row>.e-con-inner>.bp-auto{flex:0 0 auto!important}
.bp-between>.e-con-inner{justify-content:space-between!important}
.bp-center>.e-con-inner{align-items:center!important}
.bp-mid>.e-con-inner{justify-content:center!important}
.bp-g12>.e-con-inner{gap:12px!important}.bp-g16>.e-con-inner{gap:16px!important}.bp-g24>.e-con-inner{gap:24px!important}.bp-g32>.e-con-inner{gap:32px!important}
.bp-g64>.e-con-inner{gap:clamp(32px,5vw,72px)!important}
.bp-sec-sm{position:relative;isolation:isolate;overflow:hidden}
.bp-hero .elementor-heading-title,.bp-gradient .elementor-heading-title,.bp-cta .elementor-heading-title,.bp-contact .elementor-heading-title,.bp-stats .elementor-heading-title{color:#fff}
.bp-gradient .bp-t,.bp-gradient .bp-lead{color:#C9D2E8}
.bp-h1 .elementor-heading-title{font-size:clamp(38px,4.7vw,70px)}
.bp-hero{padding-bottom:120px!important}
.bp-hero-side{align-self:center!important}
.bp-stats:before,.bp-contact:before{z-index:0!important}
.bp-stats>.e-con-inner,.bp-stats>.e-con,.bp-contact>.e-con-inner{position:relative;z-index:1}
.bp-stat .elementor-counter{display:flex!important;flex-direction:column!important}
.bp-stat .elementor-counter-number-wrapper{order:1}.bp-stat .elementor-counter-title{order:2}
.bp-badge img{width:96px!important;height:auto;border-radius:12px!important;box-shadow:none!important;aspect-ratio:auto!important}
.bp-badge{padding:12px!important}
.bp-faq-side{flex:0 0 34%!important}
.bp-faq .e-n-accordion-item-title{flex-direction:row!important;justify-content:space-between!important}
.bp-faq .e-n-accordion-item-title-header{flex:1 1 auto;justify-content:flex-start!important;text-align:left}
