.bp-header.is-scrolled .bp-mainbar{background:rgba(6,11,26,.86)}
.bp-why-media{flex:0 0 42%!important}
.bp-video{align-self:center}
@media (max-width:1024px){.bp-faq-side,.bp-why-media{flex:1 1 auto!important}}
@media (max-width:767px){.bp-row>.e-con,.bp-row>.e-con-inner>.e-con{flex:1 1 auto}}
.bp-stats:before{z-index:1!important}
.bp-stats>.e-con-inner,.bp-stats>.e-con{z-index:2!important}
