.bp-cta:before{inset:0!important;background:repeating-linear-gradient(-45deg,rgba(255,255,255,.07) 0 28px,transparent 28px 56px)!important;background-size:80px 80px!important;animation:bpStripe 4s linear infinite!important;transform:none!important}
