.bp-btn-white .elementor-button-icon svg{fill:var(--bp-red)!important}.bp-btn-white .elementor-button-icon i{color:var(--bp-red)!important}
.bp .elementor-heading-title,.bp h1,.bp h2,.bp h3,.bp h4,.bp h5,.bp h6,.bp .e-n-accordion-item-title-text,.bp .elementor-image-box-title,.bp .elementor-icon-box-title,.bp .elementor-button{text-transform:none}
.bp-eyebrow .elementor-heading-title,.bp-footer .elementor-heading-title{text-transform:uppercase}
/* ===== v3: ticker / stats / one-call / footer ===== */
.bp-ticker{position:relative;z-index:2;padding:34px 0!important;overflow:hidden;background:linear-gradient(180deg,var(--bp-ink) 50%,#fff 50%)}
.bp-tk{overflow:hidden;white-space:nowrap;padding:20px 0;background:linear-gradient(90deg,var(--bp-red-2),var(--bp-red) 50%,var(--bp-red-2));transform:rotate(-1.4deg) scale(1.04);box-shadow:0 24px 50px -24px var(--bp-red-glow);border-top:1px solid rgba(255,255,255,.2);border-bottom:1px solid rgba(0,0,0,.2)}
.bp-tk-track{display:inline-flex;width:max-content;animation:bpMarq 40s linear infinite}
.bp-tk:hover .bp-tk-track{animation-play-state:paused}
.bp-tk-track span{font-family:var(--bp-fh);font-stretch:118%;font-weight:800;font-size:clamp(17px,1.8vw,24px);letter-spacing:.01em;color:#fff;text-transform:uppercase;padding:0 26px;display:inline-flex;align-items:center;white-space:nowrap}
.bp-tk-track span:after{content:"";width:9px;height:9px;transform:rotate(45deg);background:#fff;opacity:.7;margin-left:52px}
@keyframes bpMarq{to{transform:translateX(-50%)}}
/* stats */
.bp-stat .bp-num .elementor-heading-title{font-family:var(--bp-fh);font-stretch:118%;font-weight:900;font-size:clamp(42px,4.2vw,62px);line-height:1;color:#fff;letter-spacing:-.04em;white-space:nowrap}
