.bp-search{width:100%;max-width:560px;margin:8px auto 0!important}
.bp-search .elementor-search-form__container{border-radius:999px!important;overflow:hidden;background:rgba(255,255,255,.1)!important;border:1px solid rgba(255,255,255,.22)!important;-webkit-backdrop-filter:blur(12px);backdrop-filter:blur(12px);min-height:56px}
.bp-search .elementor-search-form__input{color:#fff!important;font-family:var(--bp-fb)!important;font-size:16px!important;padding-left:24px!important;background:transparent!important}
.bp-search .elementor-search-form__input::placeholder{color:rgba(225,231,245,.7)!important}
.bp-search .elementor-search-form__submit{background:linear-gradient(135deg,var(--bp-red),var(--bp-red-2))!important;min-width:64px!important;border-radius:0 999px 999px 0}
.bp-search .elementor-search-form__submit svg{fill:#fff!important;width:18px;height:18px}
/* 404 */
.bp-404{min-height:78svh}
.bp-404-copy{gap:18px!important}
.bp-404-num{font-family:var(--bp-fh);font-stretch:125%;font-weight:900;font-size:clamp(120px,22vw,260px);line-height:.8;letter-spacing:-.06em;background:linear-gradient(120deg,var(--bp-red) 10%,#FF6B5E 45%,var(--bp-blue) 90%);-webkit-background-clip:text;background-clip:text;color:transparent;text-align:center;filter:drop-shadow(0 30px 60px rgba(229,34,45,.25))}
.bp-404 .bp-btns{justify-content:center!important;margin-top:8px!important}
.bp-404-grid{max-width:1200px;margin:0 auto!important;background:#fff;border:1px solid var(--bp-line);border-radius:26px;padding:18px!important;box-shadow:var(--bp-sh)}
.bp-404-grid>.bp-mega-link:last-child:nth-child(3n+1){grid-column:1/-1}
@media (max-width:1024px){.bp-archive .elementor-posts-container{grid-template-columns:repeat(2,minmax(0,1fr))!important}}
@media (max-width:767px){.bp-archive .elementor-posts-container,.bp-404-grid{grid-template-columns:1fr!important}}
/* ===== v14: Safari/iOS fix — stacked columns must never wrap into side-by-side columns ===== */
.bp-col,.bp-col>.e-con-inner{flex-wrap:nowrap!important;--flex-wrap:nowrap;--flex-wrap-mobile:nowrap}
.bp .e-con.bp-col{--flex-wrap-mobile:nowrap}
@media (max-width:1024px){
 .bp-hero-copy,.bp-hero-side,.bp-phero-copy,.bp-post-main,.bp-post-aside{flex:1 1 auto!important;width:100%!important;max-width:100%}
 .bp-hero>.e-con-inner>.e-con{flex:1 1 auto!important}
}
@media (max-width:767px){
 .bp-f1,.bp-split-media,.bp-why-media,.bp-faq-side,.bp-faq-main,.bp-oc-media,.bp-oc-copy,.bp-frame,.bp-video,.bp-fbrand{flex:1 1 auto!important;width:100%!important;max-width:100%!important}
 .bp-row>.e-con,.bp-row>.e-con-inner>.e-con{flex:1 1 auto!important;width:100%!important;min-height:0}
 .bp-row.bp-keep>.e-con,.bp-row.bp-keep>.e-con-inner>.e-con,.bp-brands>.bp-brand,.bp-mnav .bp-mitem{width:auto!important}
 .bp-row.bp-keep>.e-con.bp-statx,.bp-stat>.e-con{flex:1 1 auto!important}
}
@media (max-width:767px){.bp-btns,.bp-btns>.e-con-inner{flex-wrap:nowrap!important;align-items:stretch}.bp-btns .elementor-button{width:100%;justify-content:center}}
